// 1. VALIDACIÓN DE ENTRADA
const body = $json.body || $json;

if (!body.consulta || typeof body.consulta !== 'string' || body.consulta.trim() === '') {
  return {
    json: {
      esValido: false,
      error: 'La consulta es obligatoria y debe ser un texto válido.'
    }
  };
}

return {
  json: {
    esValido: true,
    consulta: body.consulta.trim(),
    contexto: body.contexto || {}
  }
};

// 3. AGENTE DE NEGOCIO & FORMATEO DE RESPUESTA
// Procesa la consulta del usuario y los productos recibidos de la base de datos
const consulta = $('Validar Consulta').item.json.consulta.toLowerCase();
const contexto = $('Validar Consulta').item.json.contexto || {};

// Obtener la lista de productos de la API (o del contexto si la API no estuviera accesible)
let productos = [];
if (Array.isArray($input.all())) {
  productos = $input.all().map(item => item.json);
} else if (contexto.productos_en_alerta) {
  productos = contexto.productos_en_alerta;
}

// Identificar productos críticos (stock <= stock_minimo)
const criticos = productos.filter(p => p.stock !== undefined && p.stock_minimo !== undefined && p.stock <= p.stock_minimo);

let textoRespuesta = '';

if (consulta.includes('compra') || consulta.includes('reabastecimiento') || consulta.includes('stock')) {
  if (criticos.length === 0) {
    textoRespuesta = '📋 **INFORME DE REABASTECIMIENTO:**\n\nTodos los productos del menú cuentan con existencias saludables. No se requieren órdenes de compra urgentes.';
  } else {
    const items = criticos.map(p => 
      `- **${p.nombre}** (Stock actual: ${p.stock} unid. / Mínimo: ${p.stock_minimo})\n  👉 *Acción sugerida:* Pedir lote de **${(p.stock_minimo * 3) - p.stock} unidades** para cubrir los próximos 10 días de venta.`
    ).join('\n\n');

    textoRespuesta = `📋 **PLAN DE REABASTECIMIENTO PRIORITARIO:**\n\nSe detectaron ${criticos.length} productos con inventario igual o inferior a su umbral crítico:\n\n${items}\n\n💡 *Recomendación logística:* Priorizar el pedido de repostería con el proveedor local para garantizar productos frescos al amanecer.`;
  }
} else if (consulta.includes('promo') || consulta.includes('combo') || consulta.includes('venta')) {
  textoRespuesta = `🏷️ **ESTRATEGIA DE PROMOCIONES Y COMBOS DEL DÍA:**\n\n1. **Combo Despertar Tech ($5.25 - Ahorro 15%):**\n   - Café Americano 12oz + Croissant de Mantequilla recién horneado.\n   - *Objetivo:* Impulsar la rotación matutina y aumentar la afluencia.\n\n2. **Dúo Dulce Tarde ($6.50 Especial):**\n   - Cappuccino Italiano 8oz + Muffin de Arándanos.\n   - *Objetivo:* Elevar el ticket promedio por encima de $6.00 aprovechando la repostería del día.`;
} else {
  textoRespuesta = `☕ **ASISTENTE DE CAFETERÍA 'AROMA & CÓDIGO':**\n\nHe analizado tu consulta: "${$('Validar Consulta').item.json.consulta}".\n\n- Total productos en catálogo: **${productos.length}**\n- Productos con alerta de stock crítico: **${criticos.length}**\n\nPuedes pedirme: "Sugerir orden de compra" o "Generar promociones para hoy".`;
}

// Retornar estrictamente el contrato exigido por el laboratorio
return {
  json: {
    ok: true,
    data: {
      mensaje: textoRespuesta,
      timestamp: new Date().toISOString(),
      agente: 'Agente IA Autónomo - Aroma & Código'
    },
    error: null
  }
};
